@click.command("routes", short_help="Show the routes for the app.")
@click.option(
    "--sort",
    "-s",
    type=click.Choice(("endpoint", "methods", "domain", "rule", "match")),
    default="endpoint",
    help=(
        'Method to sort routes by. "match" is the order that Flask will match '
        "routes when dispatching a request."
    ),
)
@click.option("--all-methods", is_flag=True, help="Show HEAD and OPTIONS methods.")
@with_appcontext
def routes_command(sort: str, all_methods: bool) -> None:
    """Show all registered routes with endpoints and methods."""

    rules = list(current_app.url_map.iter_rules())
    if not rules:
        click.echo("No routes were registered.")
        return

    ignored_methods = set(() if all_methods else ("HEAD", "OPTIONS"))

    if sort in ("endpoint", "rule"):
        rules = sorted(rules, key=attrgetter(sort))
    elif sort == "methods":
        rules = sorted(rules, key=lambda rule: sorted(rule.methods))  # type: ignore
    elif sort == "domain":
        rules = sorted(
            rules, key=lambda rule: rule.host if rule.host is not None else rule.subdomain or ""
        )

    rule_methods = [
        ", ".join(sorted(rule.methods - ignored_methods))  # type: ignore
        for rule in rules
    ]

    headers = ("Endpoint", "Methods", "Rule")
    widths = (
        max(len(rule.endpoint) for rule in rules),
        max(len(methods) for methods in rule_methods),
        max(len(rule.rule) for rule in rules),
    )

    if current_app.url_map.host_matching:
        host_header = "Host"
        rule_domain = [rule.host if rule.host is not None else "" for rule in rules]
    elif any(rule.subdomain for rule in rules):
        host_header = "Subdomain"
        rule_domain = [rule.subdomain or "" for rule in rules]
    else:
        host_header = None
        rule_domain = None

    if rule_domain is not None:
        headers = (host_header, *headers)  # type: ignore[assignment]
        widths = (max(len(d) for d in rule_domain), *widths)  # type: ignore[assignment]

    widths = [max(len(h), w) for h, w in zip(headers, widths)]
    row = "  ".join(f"{{{i}:<{w}}}" for i, w in enumerate(widths))

    click.echo(row.format(*headers).strip())
    click.echo(row.format(*("-" * width for width in widths)))

    for i, (rule, methods) in enumerate(zip(rules, rule_methods)):
        if rule_domain is not None:
            click.echo(
                row.format(rule_domain[i], rule.endpoint, methods, rule.rule).rstrip()
            )
        else:
            click.echo(row.format(rule.endpoint, methods, rule.rule).rstrip())

